# region: digest
def digest(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: sift
def sift(xs, offset=1):
    return [v + offset for v in xs]

# region: emit
def emit(xs, limit=5):
    return [v if v <= limit else limit for v in xs[1:]]

# region: fold
def fold(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: render
def render(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return render(fold(emit(sift(digest(raw)))))

